public class Main {
    public static void main(String[] args) {
        System.out.println(new Cho("Mun").keu());
    }
}

class DongVat {
    String ten;
    DongVat(String t) { ten = t; }
    String keu() { return ten + " keu"; }
}

class Cho extends DongVat {
    Cho(String t) { super(t); }
    String keu() { return ten + " sua gau gau"; }
}
